// Parse billing event from CLI Market
const event = $input.item.json;

// Extract relevant data
const eventType = event.event_type || event.type;
const email = event.email || event.payer_email;
const username = event.username;
const paymentMethod = event.payment_method || 'paypal';
const activationReference = event.reference || event.subscription_id || 'N/A';
const amount = event.amount || event.amount_paid;
const currency = event.currency || 'USD';

return {
  json: {
    event_type: eventType,
    email: email,
    username: username,
    payment_method: paymentMethod,
    activation_reference: activationReference,
    amount: amount,
    currency: currency,
    timestamp: new Date().toISOString()
  }
};

// Get the most recent deal that's not already customer
const deals = $input.item.json.results || [];
const customerStage = 'customer';

const openDeals = deals.filter(deal => 
  deal.properties.dealstage !== customerStage
);

// Sort by created date descending
openDeals.sort((a, b) => 
  new Date(b.properties.createdate) - new Date(a.properties.createdate)
);

const targetDeal = openDeals[0];

if (!targetDeal) {
  throw new Error('No open deal found for contact');
}

return {
  json: {
    deal_id: targetDeal.dealId,
    current_stage: targetDeal.properties.dealstage,
    deal_name: targetDeal.properties.dealname
  }
};

// Handle non-activation events
return {
  json: {
    message: 'Event not processed: ' + $json.event_type,
    skip: true
  }
};

// Format Slack notification
const dealId = $json.deal_id;
const dealName = $json.deal_name;
const email = $node["Parse Billing Event"].json.email;
const paymentMethod = $node["Parse Billing Event"].json.payment_method;
const activationRef = $node["Parse Billing Event"].json.activation_reference;
const amount = $node["Parse Billing Event"].json.amount;
const currency = $node["Parse Billing Event"].json.currency;

const emojis = {
  'paypal': '💳',
  'mp': '🇦🇷',
  'yape': '📱',
  'plin': '📱',
  'invoice': '📄'
};

const emoji = emojis[paymentMethod.toLowerCase()] || '💰';

return {
  json: {
    channel: '#cli-market-pro',
    text: `${emoji} Pro Activated: ${email}`,
    blocks: [
      {
        type: 'header',
        text: {
          type: 'plain_text',
          text: `${emoji} Pro Activated`
        }
      },
      {
        type: 'section',
        fields: [
          {
            type: 'mrkdwn',
            text: `*Email:*\n${email}`
          },
          {
            type: 'mrkdwn',
            text: `*Payment:*\n${paymentMethod.toUpperCase()}`
          },
          {
            type: 'mrkdwn',
            text: `*Amount:*\n${amount} ${currency}`
          },
          {
            type: 'mrkdwn',
            text: `*Reference:*\n${activationRef}`
          }
        ]
      },
      {
        type: 'section',
        fields: [
          {
            type: 'mrkdwn',
            text: `*Deal:*\n${dealName}`
          },
          {
            type: 'mrkdwn',
            text: `*Deal ID:*\n${dealId}`
          }
        ]
      },
      {
        type: 'actions',
        elements: [
          {
            type: 'button',
            text: {
              type: 'plain_text',
              text: 'View in HubSpot'
            },
            url: `https://app.hubspot.com/contacts/YOUR_PORTAL/deal/${dealId}`
          }
        ]
      }
    ]
  }
};
